<?php
namespace App\Http\Controllers;
use App\Services\EnrollmentService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class EnrollmentController extends Controller {
 public function index(Request $request) {
  $request->validate(['student_id'=>'nullable|integer|exists:students,id','draft_id'=>'nullable|integer|exists:enrollments,id']);
  $preselected=[];$selectedStudent=$request->integer('student_id');$selectedPeriod=$request->integer('period_id');
  if($request->filled('draft_id')){abort_unless($request->user()->role==='registrar',403);$draft=$this->authorizeRecord($request,$request->integer('draft_id'));if(!in_array($draft->status,['special_ready','revision_requested','draft']))\App\Services\AcademicService::fail('This proposal is already published or finalized. Use the authorized revision flow.');$selectedStudent=$draft->student_id;$selectedPeriod=$draft->period_id;$preselected=app(EnrollmentService::class)->items($draft)->pluck('offering_id')->all();}
  if($selectedStudent){app(\App\Services\AccessService::class)->student($selectedStudent);if(!$preselected && $selectedPeriod){$section=DB::table('student_sections')->where(['student_id'=>$selectedStudent,'period_id'=>$selectedPeriod])->value('section_id');if($section)$preselected=DB::table('offerings')->where(['section_id'=>$section,'period_id'=>$selectedPeriod,'active'=>true])->get()->filter(function($offering)use($selectedStudent,$selectedPeriod){try{app(\App\Services\AcademicService::class)->eligible($selectedStudent,$offering->subject_id,$selectedPeriod);return true;}catch(\Illuminate\Validation\ValidationException){return false;}})->pluck('id')->all();}}
  $request->validate(['search'=>'nullable|string|max:100','period_id'=>'nullable|exists:periods,id','program_id'=>'nullable|exists:programs,id','status'=>'nullable|in:draft,proposed,special_proposed,special_ready,special_accepted,accepted,revision_requested,finalized,term_closed']);
  $query=DB::table('enrollments as e')->join('students as s','s.id','=','e.student_id')->join('users as u','u.id','=','s.user_id')->join('periods as p','p.id','=','e.period_id')->select('e.*','u.name','p.name as period','s.classification');
  if($request->user()->role==='student')$query->where('s.user_id',$request->user()->id);
  if($request->user()->role==='department_head')$query->whereIn('s.id',app(\App\Services\AccessService::class)->studentIds());
  if($request->filled('period_id'))$query->where('e.period_id',$request->integer('period_id'));if($request->filled('status'))$query->where('e.status',$request->string('status'));if($request->filled('program_id'))$query->whereIn('s.curriculum_id',DB::table('curriculums')->where('program_id',$request->integer('program_id'))->select('id'));
  if($request->filled('search'))$query->where('u.name','like','%'.mb_substr((string)$request->input('search'),0,100).'%');
  if($request->query('download')==='csv'){abort_unless($request->user()->role==='registrar',403);return response()->streamDownload(function()use($query){$out=fopen('php://output','w');fputcsv($out,['Enrollment','Student','Period','Classification','Status','Version'],',','"','');foreach($query->orderBy('e.id')->cursor() as $row){$values=[$row->id,$row->name,$row->period,$row->classification,$row->status,$row->version];$values=array_map(fn($v)=>preg_match('/^\\s*[=+@-]/u',(string)$v)?"'".$v:$v,$values);fputcsv($out,$values,',','"','');}fclose($out);},'enrollment-report.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
  $rows=\App\Support\TableQuery::sort($query,$request,['id'=>'e.id','name'=>'u.name','period'=>'p.name','classification'=>'s.classification','status'=>'e.status','version'=>'e.version'],'id','desc')->orderBy('e.id')->paginate(15)->withQueryString();if($request->expectsJson())return response()->json($rows);
  $students=DB::table('students as s')->join('users as u','u.id','=','s.user_id')->where('s.active',true)->when($request->user()->role==='department_head',fn($q)=>$q->whereIn('s.id',app(\App\Services\AccessService::class)->studentIds()))->select('s.id','u.name','s.classification','s.curriculum_id')->get();
  $periods=DB::table('periods')->where('active',true)->get();
  $offerings=DB::table('offerings as o')->join('subjects as s','s.id','=','o.subject_id')->join('sections as b','b.id','=','o.section_id')->join('periods as p','p.id','=','o.period_id')->where('o.active',true)->select('o.*','s.code','s.name','s.units','b.name as section','p.name as period')->get();
  $programs=DB::table('programs')->where('active',true)->get();$isReport=$request->routeIs('reports');return view('enrollment.index',compact('rows','students','periods','offerings','programs','isReport','preselected','selectedStudent','selectedPeriod'));
 }
 public function propose(Request $request,EnrollmentService $service) {
  $data=$request->validate(['student_id'=>'required|exists:students,id','period_id'=>'required|exists:periods,id','offering_ids'=>'required|array|min:1','offering_ids.*'=>'required|integer|distinct|exists:offerings,id']);
  $id=$service->propose($data['student_id'],$data['period_id'],$data['offering_ids'],$request->user()->role==='department_head');
  if($request->expectsJson())return response()->json(['id'=>$id,'message'=>'Proposal sent.'],201);return redirect('/enrollments/'.$id)->with('status','Proposal sent to the student for review.');
 }
 public function show(Request $request,int $id,EnrollmentService $service) {
  $e=$this->authorizeRecord($request,$id);$items=$service->items($e);
  $meetings=DB::table('schedules as c')->join('rooms as r','r.id','=','c.room_id')->join('professors as p','p.id','=','c.professor_id')->whereIn('c.offering_id',$items->pluck('offering_id'))->where('c.active',true)->select('c.*','r.code as room','p.name as professor')->get()->groupBy('offering_id');
  $versions=DB::table('cor_versions')->where('enrollment_id',$id)->orderByDesc('version')->get();
  $events=DB::table('enrollment_events')->where('enrollment_id',$id)->orderByDesc('id')->get();
  if($request->expectsJson())return response()->json(compact('e','items','meetings','events','versions'));return view('enrollment.show',compact('e','items','meetings','events','versions'));
 }
 public function decision(Request $request,int $id,EnrollmentService $service){$this->authorizeRecord($request,$id);$data=$request->validate(['version'=>'required|integer','decision'=>'required|in:accept,decline','remarks'=>'nullable|string|max:2000']);$service->decide($id,$data['version'],$data['decision']==='accept',$data['remarks']??null);return $request->expectsJson()?response()->json(['message'=>'Decision recorded.']):back()->with('status',$data['decision']==='accept'?'Enrollment finalized. Your COR is ready.':'Revision requested. Your remarks have been sent to staff.');}
 public function finalize(Request $request,int $id,EnrollmentService $service){$this->authorizeRecord($request,$id);$service->finalize($id);return $request->expectsJson()?response()->json(['message'=>'Enrollment finalized.']):back()->with('status','Enrollment finalized. The COR is available.');}
 public function cor(Request $request,int $id,?int $version=null){[$e,$snapshot,$historical]=$this->snapshot($request,$id,$version);return view('enrollment.cor',compact('snapshot','e','historical'));}
 public function pdf(Request $request,int $id,?int $version=null){[$e,$snapshot,$historical]=$this->snapshot($request,$id,$version);$pdf=new \Dompdf\Dompdf(['isRemoteEnabled'=>false]);$pdf->loadHtml(view('enrollment.pdf',compact('snapshot','e','historical'))->render());$pdf->setPaper('A4');$pdf->render();return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="COR-'.$id.'-v'.$e->version.'.pdf"']);}
 private function snapshot(Request $request,int $id,?int $version):array {$e=$this->authorizeRecord($request,$id);if($version===null)abort_unless($e->status==='finalized',404);$version=$version??$e->version;$record=DB::table('cor_versions')->where(['enrollment_id'=>$id,'version'=>$version])->first();abort_unless($record,404);$historical=$e->version!==$version || $e->status!=='finalized';$e->version=$version;return [$e,json_decode($record->snapshot),$historical];}
 public function revise(Request $request,int $id,EnrollmentService $service){$this->authorizeRecord($request,$id);$data=$request->validate(['remarks'=>'required|string|max:2000']);$service->revise($id,$data['remarks']);return redirect('/enrollments')->with('status','Enrollment reopened for an authorized revision. Previous COR versions remain in history. Send a new proposal for student acceptance.');}
 private function authorizeRecord(Request $request,int $id){$e=DB::table('enrollments as e')->join('students as s','s.id','=','e.student_id')->join('users as u','u.id','=','s.user_id')->join('periods as p','p.id','=','e.period_id')->join('curriculums as c','c.id','=','s.curriculum_id')->join('programs as pr','pr.id','=','c.program_id')->where('e.id',$id)->select('e.*','s.user_id','u.name','s.classification','s.year_level','pr.name as program','p.academic_year','p.semester','p.name as period')->first();abort_unless($e,404);app(\App\Services\AccessService::class)->student($e->student_id);if($request->user()->role==='student')abort_unless($e->user_id===$request->user()->id,403);return $e;}
}
